def sgn(x):
 return (x>0)-(x<0)
def paper_1d(points, labels):
 out=[]
 for x0 in points:
  for sense in (1.,-1.):
   scores=[-sense+sense*x/x0 for x in points]
   pred=[0 if abs(z)<1e-8 else sgn(z) for z in scores]
   reported=sum(p"'!=0 and p!=y for p,y in zip(pred,labels))
   out.append((reported,x0,sense,pred))
